// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.contactimport com.roshan.persona.connectivity.model.ContactInfoimport com.roshan.persona.connectivity.model.SimInfoimport com.roshan.persona.connectivity.model.SimPreferenceimport com.roshan.persona.connectivity.model.SimSlotimport java.util.concurrent.ConcurrentHashMap/** * NOUS — SIM Manager (Module 11 v3 — Step 11.1, India-First). * * Manages dual-SIM/eSIM intelligence — detects active SIMs + learns * per-contact SIM preference. * * ## What it does * * 1. **Detect active SIMs** — SIM1 (Jio, personal) + SIM2 (Airtel, work). * 2. **Per-contact preference** — "Call mom" → use SIM1 (auto-learned). * 3. **Auto-detect** — contacts in "Work" group → SIM2 by default. * 4. **User override** — "Call mom on SIM2 next time" → updates preference. * * ## India-first design * * Dual-SIM is the norm in India (Jio + Airtel, personal + work). * NOUS auto-learns which SIM the user prefers per contact, eliminating * the "which SIM?" prompt after the first call. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§SimManager</a> */class SimManager(    private val simService: SimService,) {    /** Per-contact SIM preferences (contactId → preference). */    private val preferences = ConcurrentHashMap<String, SimPreference>()    /**     * Get all active SIMs on the device.     */    suspend fun getActiveSims(): List<SimInfo> {        return simService.getActiveSims()    }    /**     * Get the preferred SIM for a contact.     *     * If no preference is stored, returns null (caller uses default).     *     * @param contactId the contact ID.     * @return the preferred SIM slot, or null if no preference.     */    fun getPreferredSim(contactId: String): SimSlot? {        return preferences[contactId]?.preferredSlot    }    /**     * Set the preferred SIM for a contact.     *     * @param contactId the contact ID.     * @param slot the preferred SIM slot.     * @param isAutoLearned true if NOUS auto-detected this from usage.     */    fun setPreferredSim(contactId: String, slot: SimSlot, isAutoLearned: Boolean = false) {        preferences[contactId] = SimPreference(            contactId = contactId,            preferredSlot = slot,            isAutoLearned = isAutoLearned,        )    }    /**     * Auto-learn SIM preference from a call.     *     * Called after a call is placed — if the user manually selected a SIM,     * NOUS remembers it for future calls to the same contact.     *     * @param contactId the contact that was called.     * @param usedSlot which SIM was used for the call.     */    fun autoLearnFromCall(contactId: String, usedSlot: SimSlot) {        // Only auto-learn if no explicit preference exists, or if the        // existing preference was auto-learned (not user-set).        val existing = preferences[contactId]        if (existing == null || existing.isAutoLearned) {            setPreferredSim(contactId, usedSlot, isAutoLearned = true)        }    }    /**     * Clear SIM preference for a contact.     */    fun clearPreference(contactId: String) {        preferences.remove(contactId)    }    /**     * Clear all SIM preferences.     */    fun clearAll() {        preferences.clear()    }    /**     * Get all stored SIM preferences.     */    fun getAllPreferences(): List<SimPreference> = preferences.values.toList()}// ──────────────────────────────────────────────────────────────────────────/** * SIM service interface — wraps Android's SubscriptionManager. * * Real implementation queries SubscriptionManager for active SIMs. * Tests inject a fake. */interface SimService {    /** Get all active SIMs on the device. */    suspend fun getActiveSims(): List<SimInfo>}